import sys
from collections import deque
input = sys.stdin.readline
LOG = 17

n, q = map(int, input().split())
adj = [[] for _ in range(n + 1)]
for _ in range(n - 1):
    u, v = map(int, input().split())
    adj[u].append(v)
    adj[v].append(u)

depth = [0] * (n + 1)
up = [[0] * (n + 1) for _ in range(LOG)]

# BFS to compute depth and up[0]
visited = [False] * (n + 1)
queue = deque([1])
visited[1] = True
while queue:
    node = queue.popleft()
    for nb in adj[node]:
        if not visited[nb]:
            visited[nb] = True
            depth[nb] = depth[node] + 1
            up[0][nb] = node
            queue.append(nb)

# Fill sparse table
for k in range(1, LOG):
    for v in range(1, n + 1):
        up[k][v] = up[k-1][up[k-1][v]]

def lca(u, v):
    if depth[u] < depth[v]:
        u, v = v, u
    diff = depth[u] - depth[v]
    for k in range(LOG):
        if (diff >> k) & 1:
            u = up[k][u]
    if u == v:
        return u
    for k in range(LOG - 1, -1, -1):
        if up[k][u] != up[k][v]:
            u = up[k][u]
            v = up[k][v]
    return up[0][u]

for _ in range(q):
    u, v = map(int, input().split())
    print(lca(u, v))

