using namespace std;
const int LOG = 17;
int up[LOG][100001], depth[100001];
vector<int> adj[100001];
void bfs(int root, int n) {
    queue<int> Q;
    vector<bool> vis(n+1,false);
    Q.push(root); vis[root]=true; up[0][root]=root;
    while(!Q.empty()){
        int u=Q.front();Q.pop();
        for(int v:adj[u]) if(!vis[v]){
            vis[v]=true; depth[v]=depth[u]+1; up[0][v]=u; Q.push(v);
        }
    }
    for(int k=1;k<LOG;k++)
        for(int v=1;v<=n;v++)
            up[k][v]=up[k-1][up[k-1][v]];
}
int lca(int u,int v){
    if(depth[u]<depth[v]) swap(u,v);
    int d=depth[u]-depth[v];
    for(int k=0;k<LOG;k++) if((d>>k)&1) u=up[k][u];
    if(u==v) return u;
    for(int k=LOG-1;k>=0;k--) if(up[k][u]!=up[k][v]){u=up[k][u];v=up[k][v];}
    return up[0][u];
}
