import java.util.*;
public class Main {
    static final int LOG=17;
    static int[][] up=new int[LOG][100001];
    static int[] depth=new int[100001];
    static List<Integer>[] adj;
    @SuppressWarnings("unchecked")
    public static void main(String[] args){
        Scanner sc=new Scanner(System.in);
        int n=sc.nextInt(),q=sc.nextInt();
        adj=new List[n+1];
        for(int i=0;i<=n;i++) adj[i]=new ArrayList<>();
        for(int i=0;i<n-1;i++){int u=sc.nextInt(),v=sc.nextInt();adj[u].add(v);adj[v].add(u);}
        // BFS
        boolean[] vis=new boolean[n+1];
        Queue<Integer> bfs=new LinkedList<>();
        bfs.add(1);vis[1]=true;up[0][1]=1;
        while(!bfs.isEmpty()){
            int u=bfs.poll();
            for(int v:adj[u]) if(!vis[v]){
                vis[v]=true;depth[v]=depth[u]+1;up[0][v]=u;bfs.add(v);
            }
        }
        for(int k=1;k<LOG;k++)
            for(int v=1;v<=n;v++)
                up[k][v]=up[k-1][up[k-1][v]];
        while(q-->0){
            int u=sc.nextInt(),v=sc.nextInt();
            if(depth[u]<depth[v]){int t=u;u=v;v=t;}
            int d=depth[u]-depth[v];
            for(int k=0;k<LOG;k++) if(((d>>k)&1)!=0) u=up[k][u];
            if(u!=v){
                for(int k=LOG-1;k>=0;k--) if(up[k][u]!=up[k][v]){u=up[k][u];v=up[k][v];}
                u=up[0][u];
            }
            System.out.println(u);
        }
    }
